18: internal static class RequirementStoredTimestamp
19: {
20:     /// <summary>
21:     /// Reads one stored time, keeping its stored offset; a value without an offset reads as UTC. A value without a
22:     /// complete date (a time alone, or a date without its year) reads as null: the framework fills a missing date or
23:     /// year from the clock, so the year the parse reports must be written, as four digits, in the stored text.
24:     /// </summary>
25:     /// <param name="stored">The stored text.</param>
26:     /// <returns>The stored time, or null when nothing readable with a complete date is stored.</returns>
27:     internal static DateTimeOffset? Read(string? stored) =>
28:         !string.IsNullOrWhiteSpace(stored)
29:         && DateTimeOffset.TryParse(stored, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out var value)
30:         && stored.Contains(value.Year.ToString("D4", CultureInfo.InvariantCulture), StringComparison.Ordinal)
31:             ? value
32:             : null;
33: 
34:     /// <summary>Reads the earliest readable stored time, for a mapping that aggregates several links.</summary>
35:     /// <param name="stored">The links' stored creation texts.</param>
36:     /// <returns>The earliest stored time, or null when none is readable.</returns>
37:     internal static DateTimeOffset? Earliest(IEnumerable<string?> stored)
38:     {
39:         ArgumentNullException.ThrowIfNull(stored);
40:         DateTimeOffset? earliest = null;
41:         foreach (var value in stored.Select(Read))
42:         {
43:             if (value is not null && (earliest is null || value.Value < earliest.Value))
44:                 earliest = value;
45:         }
46: 
47:         return earliest;
48:     }
